INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Saturn', 'Sun', 'quincunx', 'Sự lệch pha và đòi hỏi sự tái điều chỉnh liên tục giữa Sao Thổ (tính kỷ luật, tinh thần trách nhiệm và các giới hạn) và Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng). Hai năng lượng không có điểm chung tự nhiên.', 'Trong cuộc sống hàng ngày, bạn hay phải loay hoay điều chỉnh để tính kỷ luật, tinh thần trách nhiệm và các giới hạn không làm gián đoạn hoặc mâu thuẫn với ý chí cá nhân, bản ngã và khát vọng tỏa sáng.', 'Khả năng giải quyết vấn đề linh hoạt, tinh thần tháo vát và năng lực thích nghi với những tình huống không lường trước. (Sao Thổ - Mặt Trời)', 'Dễ bị mệt mỏi tinh thần hoặc căng thẳng sức khỏe nhẹ do phải liên tục điều chỉnh nhịp sống. (Sao Thổ - Mặt Trời)', '', '', ARRAY['Góc chiếu Bất Bất Hợp', 'Sao Thổ', 'Mặt Trời']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Sun', 'Uranus', 'conjunction', 'Sự hợp nhất mạnh mẽ giữa Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng) và Sao Thiên Vương (tư duy đổi mới, tính độc lập và sự đột phá). Hai nguồn năng lượng hòa làm một, tạo nên điểm nhấn cá tính vô cùng mãnh liệt.', 'Trong cuộc sống hàng ngày, bạn thể hiện ý chí cá nhân, bản ngã và khát vọng tỏa sáng và tư duy đổi mới, tính độc lập và sự đột phá một cách đồng thời. Bạn hành động bộc phát theo bản năng hòa quyện của cả hai hành tinh.', 'Khả năng tập trung năng lượng vượt trội, sự nhất quán nội tâm cao và sức mạnh bộc lộ cá tính ấn tượng. (Mặt Trời - Sao Thiên Vương)', 'Khó phân tách giữa các nhu cầu khác nhau. Dễ bị cuốn vào sự chủ quan và thiếu cái nhìn khách quan đa chiều. (Mặt Trời - Sao Thiên Vương)', '', '', ARRAY['Góc chiếu Trùng Hợp', 'Mặt Trời', 'Sao Thiên Vương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Sun', 'Uranus', 'sextile', 'Sự hỗ trợ cơ hội và tạo điều kiện thuận lợi giữa Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng) và Sao Thiên Vương (tư duy đổi mới, tính độc lập và sự đột phá). Năng lượng tuôn chảy nhẹ nhàng, kích thích sự phát triển.', 'Trong cuộc sống hàng ngày, bạn dễ dàng kết hợp ý chí cá nhân, bản ngã và khát vọng tỏa sáng với tư duy đổi mới, tính độc lập và sự đột phá để tạo ra những kết quả tích cực và nắm bắt cơ hội hiệu quả.', 'Tư duy linh hoạt, khả năng giao tiếp và kết nối tốt, tinh thần chủ động học hỏi và thích ứng nhanh. (Mặt Trời - Sao Thiên Vương)', 'Nếu không chủ động rèn luyện và tự đặt ra mục tiêu, các cơ hội thuận lợi có thể bị trôi qua một cách đáng tiếc. (Mặt Trời - Sao Thiên Vương)', '', '', ARRAY['Góc chiếu Lục Hợp', 'Mặt Trời', 'Sao Thiên Vương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Sun', 'Uranus', 'trine', 'Dòng chảy năng lượng hài hòa và may mắn tự nhiên giữa Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng) và Sao Thiên Vương (tư duy đổi mới, tính độc lập và sự đột phá). Hai hành tinh bổ trợ cho nhau một cách hoàn hảo.', 'Trong cuộc sống hàng ngày, sự kết hợp giữa ý chí cá nhân, bản ngã và khát vọng tỏa sáng và tư duy đổi mới, tính độc lập và sự đột phá diễn ra một cách tự nhiên mà không cần đến nhiều nỗ lực hay sự gượng ép.', 'Tài năng bẩm sinh, tâm hồn an ổn, sức hút tự nhiên và khả năng gặt hái thành công một cách trôi chảy. (Mặt Trời - Sao Thiên Vương)', 'Có nguy cơ sinh ra tâm lý tự mãn, thiếu động lực bứt phá khi gặp phải thử thách thật sự lớn. (Mặt Trời - Sao Thiên Vương)', '', '', ARRAY['Góc chiếu Tam Hợp', 'Mặt Trời', 'Sao Thiên Vương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Sun', 'Uranus', 'square', 'Sự căng thẳng và xung đột nội tâm giữa Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng) và Sao Thiên Vương (tư duy đổi mới, tính độc lập và sự đột phá). Đây là động lực áp lực thúc đẩy sự trưởng thành vượt bậc.', 'Trong cuộc sống hàng ngày, bạn thường xuyên cảm thấy sự giằng xé giữa nhu cầu về ý chí cá nhân, bản ngã và khát vọng tỏa sáng và đòi hỏi từ tư duy đổi mới, tính độc lập và sự đột phá.', 'Ý chí kiên cường, bản lĩnh vượt khó phi thường và khả năng biến áp lực xung đột thành động lực vươn lên. (Mặt Trời - Sao Thiên Vương)', 'Dễ rơi vào trạng thái căng thẳng thần kinh, bực bội nội tâm và xung đột trong các mối quan hệ khi chưa kiểm soát được năng lượng. (Mặt Trời - Sao Thiên Vương)', '', '', ARRAY['Góc chiếu Vuông Góc', 'Mặt Trời', 'Sao Thiên Vương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Sun', 'Uranus', 'opposition', 'Sự đối lập và nhu cầu cân bằng giữa Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng) và Sao Thiên Vương (tư duy đổi mới, tính độc lập và sự đột phá). Hai mặt của một trục năng lượng cần được dung hòa.', 'Trong cuộc sống hàng ngày, bạn hay thấy mình đứng giữa hai cực: một bên là ý chí cá nhân, bản ngã và khát vọng tỏa sáng và bên kia là tư duy đổi mới, tính độc lập và sự đột phá, thường phóng chiếu lên người đối diện.', 'Tầm nhìn khách quan đa chiều, khả năng thấu hiểu tâm lý đối phương và năng lực đàm phán, dung hòa tuyệt vời khi đã trưởng thành. (Mặt Trời - Sao Thiên Vương)', 'Thường xuyên cảm thấy dao động trồi sụt, mâu thuẫn giữa nhu cầu cá nhân và kỳ vọng từ mối quan hệ bên ngoài. (Mặt Trời - Sao Thiên Vương)', '', '', ARRAY['Góc chiếu Xung Chiếu', 'Mặt Trời', 'Sao Thiên Vương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Sun', 'Uranus', 'semi-sextile', 'Sự tương tác tinh tế đòi hỏi sự điều chỉnh nhỏ giữa Mặt Trời (ý chí cá nhân, bản ngã và khát vọng tỏa sáng) và Sao Thiên Vương (tư duy đổi mới, tính độc lập và sự đột phá). Hai năng lượng kề nhau cần sự thấu hiểu vi mô.', 'Trong cuộc sống hàng ngày, bạn nhận thấy những khác biệt nhỏ nhưng liên tục giữa ý chí cá nhân, bản ngã và khát vọng tỏa sáng và tư duy đổi mới, tính độc lập và sự đột phá, thúc đẩy bạn tinh chỉnh thái độ.', 'Khả năng quan sát tinh tế, sự nhạy cảm với các chi tiết nhỏ và khả năng thích ứng linh hoạt trong ứng xử. (Mặt Trời - Sao Thiên Vương)', 'Cảm giác lấn cấn nhỏ dai dẳng nếu không chú ý lắng nghe và dung hòa các nhu cầu vi mô của bản thân. (Mặt Trời - Sao Thiên Vương)', '', '', ARRAY['Góc chiếu Bán Lục Hợp', 'Mặt Trời', 'Sao Thiên Vương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
