INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Moon', 'Venus', 'conjunction', 'Sự hợp nhất mạnh mẽ giữa Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng) và Sao Kim (tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ). Hai nguồn năng lượng hòa làm một, tạo nên điểm nhấn cá tính vô cùng mãnh liệt.', 'Trong cuộc sống hàng ngày, bạn thể hiện thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng và tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ một cách đồng thời. Bạn hành động bộc phát theo bản năng hòa quyện của cả hai hành tinh.', 'Khả năng tập trung năng lượng vượt trội, sự nhất quán nội tâm cao và sức mạnh bộc lộ cá tính ấn tượng. (Mặt Trăng - Sao Kim)', 'Khó phân tách giữa các nhu cầu khác nhau. Dễ bị cuốn vào sự chủ quan và thiếu cái nhìn khách quan đa chiều. (Mặt Trăng - Sao Kim)', '', '', ARRAY['Góc chiếu Trùng Hợp', 'Mặt Trăng', 'Sao Kim']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Moon', 'Venus', 'sextile', 'Sự hỗ trợ cơ hội và tạo điều kiện thuận lợi giữa Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng) và Sao Kim (tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ). Năng lượng tuôn chảy nhẹ nhàng, kích thích sự phát triển.', 'Trong cuộc sống hàng ngày, bạn dễ dàng kết hợp thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng với tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ để tạo ra những kết quả tích cực và nắm bắt cơ hội hiệu quả.', 'Tư duy linh hoạt, khả năng giao tiếp và kết nối tốt, tinh thần chủ động học hỏi và thích ứng nhanh. (Mặt Trăng - Sao Kim)', 'Nếu không chủ động rèn luyện và tự đặt ra mục tiêu, các cơ hội thuận lợi có thể bị trôi qua một cách đáng tiếc. (Mặt Trăng - Sao Kim)', '', '', ARRAY['Góc chiếu Lục Hợp', 'Mặt Trăng', 'Sao Kim']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Moon', 'Venus', 'trine', 'Dòng chảy năng lượng hài hòa và may mắn tự nhiên giữa Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng) và Sao Kim (tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ). Hai hành tinh bổ trợ cho nhau một cách hoàn hảo.', 'Trong cuộc sống hàng ngày, sự kết hợp giữa thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng và tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ diễn ra một cách tự nhiên mà không cần đến nhiều nỗ lực hay sự gượng ép.', 'Tài năng bẩm sinh, tâm hồn an ổn, sức hút tự nhiên và khả năng gặt hái thành công một cách trôi chảy. (Mặt Trăng - Sao Kim)', 'Có nguy cơ sinh ra tâm lý tự mãn, thiếu động lực bứt phá khi gặp phải thử thách thật sự lớn. (Mặt Trăng - Sao Kim)', '', '', ARRAY['Góc chiếu Tam Hợp', 'Mặt Trăng', 'Sao Kim']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Moon', 'Venus', 'square', 'Sự căng thẳng và xung đột nội tâm giữa Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng) và Sao Kim (tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ). Đây là động lực áp lực thúc đẩy sự trưởng thành vượt bậc.', 'Trong cuộc sống hàng ngày, bạn thường xuyên cảm thấy sự giằng xé giữa nhu cầu về thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng và đòi hỏi từ tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ.', 'Ý chí kiên cường, bản lĩnh vượt khó phi thường và khả năng biến áp lực xung đột thành động lực vươn lên. (Mặt Trăng - Sao Kim)', 'Dễ rơi vào trạng thái căng thẳng thần kinh, bực bội nội tâm và xung đột trong các mối quan hệ khi chưa kiểm soát được năng lượng. (Mặt Trăng - Sao Kim)', '', '', ARRAY['Góc chiếu Vuông Góc', 'Mặt Trăng', 'Sao Kim']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Moon', 'Venus', 'opposition', 'Sự đối lập và nhu cầu cân bằng giữa Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng) và Sao Kim (tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ). Hai mặt của một trục năng lượng cần được dung hòa.', 'Trong cuộc sống hàng ngày, bạn hay thấy mình đứng giữa hai cực: một bên là thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng và bên kia là tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ, thường phóng chiếu lên người đối diện.', 'Tầm nhìn khách quan đa chiều, khả năng thấu hiểu tâm lý đối phương và năng lực đàm phán, dung hòa tuyệt vời khi đã trưởng thành. (Mặt Trăng - Sao Kim)', 'Thường xuyên cảm thấy dao động trồi sụt, mâu thuẫn giữa nhu cầu cá nhân và kỳ vọng từ mối quan hệ bên ngoài. (Mặt Trăng - Sao Kim)', '', '', ARRAY['Góc chiếu Xung Chiếu', 'Mặt Trăng', 'Sao Kim']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Moon', 'Venus', 'semi-sextile', 'Sự tương tác tinh tế đòi hỏi sự điều chỉnh nhỏ giữa Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng) và Sao Kim (tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ). Hai năng lượng kề nhau cần sự thấu hiểu vi mô.', 'Trong cuộc sống hàng ngày, bạn nhận thấy những khác biệt nhỏ nhưng liên tục giữa thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng và tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ, thúc đẩy bạn tinh chỉnh thái độ.', 'Khả năng quan sát tinh tế, sự nhạy cảm với các chi tiết nhỏ và khả năng thích ứng linh hoạt trong ứng xử. (Mặt Trăng - Sao Kim)', 'Cảm giác lấn cấn nhỏ dai dẳng nếu không chú ý lắng nghe và dung hòa các nhu cầu vi mô của bản thân. (Mặt Trăng - Sao Kim)', '', '', ARRAY['Góc chiếu Bán Lục Hợp', 'Mặt Trăng', 'Sao Kim']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Moon', 'Venus', 'quincunx', 'Sự lệch pha và đòi hỏi sự tái điều chỉnh liên tục giữa Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng) và Sao Kim (tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ). Hai năng lượng không có điểm chung tự nhiên.', 'Trong cuộc sống hàng ngày, bạn hay phải loay hoay điều chỉnh để thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng không làm gián đoạn hoặc mâu thuẫn với tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ.', 'Khả năng giải quyết vấn đề linh hoạt, tinh thần tháo vát và năng lực thích nghi với những tình huống không lường trước. (Mặt Trăng - Sao Kim)', 'Dễ bị mệt mỏi tinh thần hoặc căng thẳng sức khỏe nhẹ do phải liên tục điều chỉnh nhịp sống. (Mặt Trăng - Sao Kim)', '', '', ARRAY['Góc chiếu Bất Bất Hợp', 'Mặt Trăng', 'Sao Kim']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mars', 'Moon', 'conjunction', 'Sự hợp nhất mạnh mẽ giữa Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục) và Mặt Trăng (thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng). Hai nguồn năng lượng hòa làm một, tạo nên điểm nhấn cá tính vô cùng mãnh liệt.', 'Trong cuộc sống hàng ngày, bạn thể hiện năng lượng hành động, lòng dũng cảm và ham muốn chinh phục và thế giới nội tâm, cảm xúc và bản năng nuôi dưỡng một cách đồng thời. Bạn hành động bộc phát theo bản năng hòa quyện của cả hai hành tinh.', 'Khả năng tập trung năng lượng vượt trội, sự nhất quán nội tâm cao và sức mạnh bộc lộ cá tính ấn tượng. (Sao Hỏa - Mặt Trăng)', 'Khó phân tách giữa các nhu cầu khác nhau. Dễ bị cuốn vào sự chủ quan và thiếu cái nhìn khách quan đa chiều. (Sao Hỏa - Mặt Trăng)', '', '', ARRAY['Góc chiếu Trùng Hợp', 'Sao Hỏa', 'Mặt Trăng']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
