INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Neptune', 'Venus', 'semi-sextile', 'Sự tương tác tinh tế đòi hỏi sự điều chỉnh nhỏ giữa Sao Hải Vương (trực giác tâm linh, trí tưởng tượng và lòng vị tha) và Sao Kim (tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ). Hai năng lượng kề nhau cần sự thấu hiểu vi mô.', 'Trong cuộc sống hàng ngày, bạn nhận thấy những khác biệt nhỏ nhưng liên tục giữa trực giác tâm linh, trí tưởng tượng và lòng vị tha và tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ, thúc đẩy bạn tinh chỉnh thái độ.', 'Khả năng quan sát tinh tế, sự nhạy cảm với các chi tiết nhỏ và khả năng thích ứng linh hoạt trong ứng xử. (Sao Hải Vương - Sao Kim)', 'Cảm giác lấn cấn nhỏ dai dẳng nếu không chú ý lắng nghe và dung hòa các nhu cầu vi mô của bản thân. (Sao Hải Vương - Sao Kim)', '', '', ARRAY['Góc chiếu Bán Lục Hợp', 'Sao Hải Vương', 'Sao Kim']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Neptune', 'Venus', 'quincunx', 'Sự lệch pha và đòi hỏi sự tái điều chỉnh liên tục giữa Sao Hải Vương (trực giác tâm linh, trí tưởng tượng và lòng vị tha) và Sao Kim (tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ). Hai năng lượng không có điểm chung tự nhiên.', 'Trong cuộc sống hàng ngày, bạn hay phải loay hoay điều chỉnh để trực giác tâm linh, trí tưởng tượng và lòng vị tha không làm gián đoạn hoặc mâu thuẫn với tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ.', 'Khả năng giải quyết vấn đề linh hoạt, tinh thần tháo vát và năng lực thích nghi với những tình huống không lường trước. (Sao Hải Vương - Sao Kim)', 'Dễ bị mệt mỏi tinh thần hoặc căng thẳng sức khỏe nhẹ do phải liên tục điều chỉnh nhịp sống. (Sao Hải Vương - Sao Kim)', '', '', ARRAY['Góc chiếu Bất Bất Hợp', 'Sao Hải Vương', 'Sao Kim']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Pluto', 'Venus', 'conjunction', 'Sự hợp nhất mạnh mẽ giữa Sao Diêm Vương (sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh) và Sao Kim (tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ). Hai nguồn năng lượng hòa làm một, tạo nên điểm nhấn cá tính vô cùng mãnh liệt.', 'Trong cuộc sống hàng ngày, bạn thể hiện sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh và tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ một cách đồng thời. Bạn hành động bộc phát theo bản năng hòa quyện của cả hai hành tinh.', 'Khả năng tập trung năng lượng vượt trội, sự nhất quán nội tâm cao và sức mạnh bộc lộ cá tính ấn tượng. (Sao Diêm Vương - Sao Kim)', 'Khó phân tách giữa các nhu cầu khác nhau. Dễ bị cuốn vào sự chủ quan và thiếu cái nhìn khách quan đa chiều. (Sao Diêm Vương - Sao Kim)', '', '', ARRAY['Góc chiếu Trùng Hợp', 'Sao Diêm Vương', 'Sao Kim']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Pluto', 'Venus', 'sextile', 'Sự hỗ trợ cơ hội và tạo điều kiện thuận lợi giữa Sao Diêm Vương (sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh) và Sao Kim (tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ). Năng lượng tuôn chảy nhẹ nhàng, kích thích sự phát triển.', 'Trong cuộc sống hàng ngày, bạn dễ dàng kết hợp sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh với tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ để tạo ra những kết quả tích cực và nắm bắt cơ hội hiệu quả.', 'Tư duy linh hoạt, khả năng giao tiếp và kết nối tốt, tinh thần chủ động học hỏi và thích ứng nhanh. (Sao Diêm Vương - Sao Kim)', 'Nếu không chủ động rèn luyện và tự đặt ra mục tiêu, các cơ hội thuận lợi có thể bị trôi qua một cách đáng tiếc. (Sao Diêm Vương - Sao Kim)', '', '', ARRAY['Góc chiếu Lục Hợp', 'Sao Diêm Vương', 'Sao Kim']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Pluto', 'Venus', 'trine', 'Dòng chảy năng lượng hài hòa và may mắn tự nhiên giữa Sao Diêm Vương (sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh) và Sao Kim (tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ). Hai hành tinh bổ trợ cho nhau một cách hoàn hảo.', 'Trong cuộc sống hàng ngày, sự kết hợp giữa sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh và tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ diễn ra một cách tự nhiên mà không cần đến nhiều nỗ lực hay sự gượng ép.', 'Tài năng bẩm sinh, tâm hồn an ổn, sức hút tự nhiên và khả năng gặt hái thành công một cách trôi chảy. (Sao Diêm Vương - Sao Kim)', 'Có nguy cơ sinh ra tâm lý tự mãn, thiếu động lực bứt phá khi gặp phải thử thách thật sự lớn. (Sao Diêm Vương - Sao Kim)', '', '', ARRAY['Góc chiếu Tam Hợp', 'Sao Diêm Vương', 'Sao Kim']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Pluto', 'Venus', 'square', 'Sự căng thẳng và xung đột nội tâm giữa Sao Diêm Vương (sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh) và Sao Kim (tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ). Đây là động lực áp lực thúc đẩy sự trưởng thành vượt bậc.', 'Trong cuộc sống hàng ngày, bạn thường xuyên cảm thấy sự giằng xé giữa nhu cầu về sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh và đòi hỏi từ tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ.', 'Ý chí kiên cường, bản lĩnh vượt khó phi thường và khả năng biến áp lực xung đột thành động lực vươn lên. (Sao Diêm Vương - Sao Kim)', 'Dễ rơi vào trạng thái căng thẳng thần kinh, bực bội nội tâm và xung đột trong các mối quan hệ khi chưa kiểm soát được năng lượng. (Sao Diêm Vương - Sao Kim)', '', '', ARRAY['Góc chiếu Vuông Góc', 'Sao Diêm Vương', 'Sao Kim']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Pluto', 'Venus', 'opposition', 'Sự đối lập và nhu cầu cân bằng giữa Sao Diêm Vương (sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh) và Sao Kim (tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ). Hai mặt của một trục năng lượng cần được dung hòa.', 'Trong cuộc sống hàng ngày, bạn hay thấy mình đứng giữa hai cực: một bên là sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh và bên kia là tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ, thường phóng chiếu lên người đối diện.', 'Tầm nhìn khách quan đa chiều, khả năng thấu hiểu tâm lý đối phương và năng lực đàm phán, dung hòa tuyệt vời khi đã trưởng thành. (Sao Diêm Vương - Sao Kim)', 'Thường xuyên cảm thấy dao động trồi sụt, mâu thuẫn giữa nhu cầu cá nhân và kỳ vọng từ mối quan hệ bên ngoài. (Sao Diêm Vương - Sao Kim)', '', '', ARRAY['Góc chiếu Xung Chiếu', 'Sao Diêm Vương', 'Sao Kim']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
