INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Mars', 'conjunction', 'Sự hợp nhất mạnh mẽ giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục). Hai nguồn năng lượng hòa làm một, tạo nên điểm nhấn cá tính vô cùng mãnh liệt.', 'Trong cuộc sống hàng ngày, bạn thể hiện niềm tin, sự may mắn và khát vọng phát triển tri thức và năng lượng hành động, lòng dũng cảm và ham muốn chinh phục một cách đồng thời. Bạn hành động bộc phát theo bản năng hòa quyện của cả hai hành tinh.', 'Khả năng tập trung năng lượng vượt trội, sự nhất quán nội tâm cao và sức mạnh bộc lộ cá tính ấn tượng. (Sao Mộc - Sao Hỏa)', 'Khó phân tách giữa các nhu cầu khác nhau. Dễ bị cuốn vào sự chủ quan và thiếu cái nhìn khách quan đa chiều. (Sao Mộc - Sao Hỏa)', '', '', ARRAY['Góc chiếu Trùng Hợp', 'Sao Mộc', 'Sao Hỏa']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Mars', 'sextile', 'Sự hỗ trợ cơ hội và tạo điều kiện thuận lợi giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục). Năng lượng tuôn chảy nhẹ nhàng, kích thích sự phát triển.', 'Trong cuộc sống hàng ngày, bạn dễ dàng kết hợp niềm tin, sự may mắn và khát vọng phát triển tri thức với năng lượng hành động, lòng dũng cảm và ham muốn chinh phục để tạo ra những kết quả tích cực và nắm bắt cơ hội hiệu quả.', 'Tư duy linh hoạt, khả năng giao tiếp và kết nối tốt, tinh thần chủ động học hỏi và thích ứng nhanh. (Sao Mộc - Sao Hỏa)', 'Nếu không chủ động rèn luyện và tự đặt ra mục tiêu, các cơ hội thuận lợi có thể bị trôi qua một cách đáng tiếc. (Sao Mộc - Sao Hỏa)', '', '', ARRAY['Góc chiếu Lục Hợp', 'Sao Mộc', 'Sao Hỏa']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Mars', 'trine', 'Dòng chảy năng lượng hài hòa và may mắn tự nhiên giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục). Hai hành tinh bổ trợ cho nhau một cách hoàn hảo.', 'Trong cuộc sống hàng ngày, sự kết hợp giữa niềm tin, sự may mắn và khát vọng phát triển tri thức và năng lượng hành động, lòng dũng cảm và ham muốn chinh phục diễn ra một cách tự nhiên mà không cần đến nhiều nỗ lực hay sự gượng ép.', 'Tài năng bẩm sinh, tâm hồn an ổn, sức hút tự nhiên và khả năng gặt hái thành công một cách trôi chảy. (Sao Mộc - Sao Hỏa)', 'Có nguy cơ sinh ra tâm lý tự mãn, thiếu động lực bứt phá khi gặp phải thử thách thật sự lớn. (Sao Mộc - Sao Hỏa)', '', '', ARRAY['Góc chiếu Tam Hợp', 'Sao Mộc', 'Sao Hỏa']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Mars', 'square', 'Sự căng thẳng và xung đột nội tâm giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục). Đây là động lực áp lực thúc đẩy sự trưởng thành vượt bậc.', 'Trong cuộc sống hàng ngày, bạn thường xuyên cảm thấy sự giằng xé giữa nhu cầu về niềm tin, sự may mắn và khát vọng phát triển tri thức và đòi hỏi từ năng lượng hành động, lòng dũng cảm và ham muốn chinh phục.', 'Ý chí kiên cường, bản lĩnh vượt khó phi thường và khả năng biến áp lực xung đột thành động lực vươn lên. (Sao Mộc - Sao Hỏa)', 'Dễ rơi vào trạng thái căng thẳng thần kinh, bực bội nội tâm và xung đột trong các mối quan hệ khi chưa kiểm soát được năng lượng. (Sao Mộc - Sao Hỏa)', '', '', ARRAY['Góc chiếu Vuông Góc', 'Sao Mộc', 'Sao Hỏa']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Mars', 'opposition', 'Sự đối lập và nhu cầu cân bằng giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục). Hai mặt của một trục năng lượng cần được dung hòa.', 'Trong cuộc sống hàng ngày, bạn hay thấy mình đứng giữa hai cực: một bên là niềm tin, sự may mắn và khát vọng phát triển tri thức và bên kia là năng lượng hành động, lòng dũng cảm và ham muốn chinh phục, thường phóng chiếu lên người đối diện.', 'Tầm nhìn khách quan đa chiều, khả năng thấu hiểu tâm lý đối phương và năng lực đàm phán, dung hòa tuyệt vời khi đã trưởng thành. (Sao Mộc - Sao Hỏa)', 'Thường xuyên cảm thấy dao động trồi sụt, mâu thuẫn giữa nhu cầu cá nhân và kỳ vọng từ mối quan hệ bên ngoài. (Sao Mộc - Sao Hỏa)', '', '', ARRAY['Góc chiếu Xung Chiếu', 'Sao Mộc', 'Sao Hỏa']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Mars', 'semi-sextile', 'Sự tương tác tinh tế đòi hỏi sự điều chỉnh nhỏ giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục). Hai năng lượng kề nhau cần sự thấu hiểu vi mô.', 'Trong cuộc sống hàng ngày, bạn nhận thấy những khác biệt nhỏ nhưng liên tục giữa niềm tin, sự may mắn và khát vọng phát triển tri thức và năng lượng hành động, lòng dũng cảm và ham muốn chinh phục, thúc đẩy bạn tinh chỉnh thái độ.', 'Khả năng quan sát tinh tế, sự nhạy cảm với các chi tiết nhỏ và khả năng thích ứng linh hoạt trong ứng xử. (Sao Mộc - Sao Hỏa)', 'Cảm giác lấn cấn nhỏ dai dẳng nếu không chú ý lắng nghe và dung hòa các nhu cầu vi mô của bản thân. (Sao Mộc - Sao Hỏa)', '', '', ARRAY['Góc chiếu Bán Lục Hợp', 'Sao Mộc', 'Sao Hỏa']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Mars', 'quincunx', 'Sự lệch pha và đòi hỏi sự tái điều chỉnh liên tục giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục). Hai năng lượng không có điểm chung tự nhiên.', 'Trong cuộc sống hàng ngày, bạn hay phải loay hoay điều chỉnh để niềm tin, sự may mắn và khát vọng phát triển tri thức không làm gián đoạn hoặc mâu thuẫn với năng lượng hành động, lòng dũng cảm và ham muốn chinh phục.', 'Khả năng giải quyết vấn đề linh hoạt, tinh thần tháo vát và năng lực thích nghi với những tình huống không lường trước. (Sao Mộc - Sao Hỏa)', 'Dễ bị mệt mỏi tinh thần hoặc căng thẳng sức khỏe nhẹ do phải liên tục điều chỉnh nhịp sống. (Sao Mộc - Sao Hỏa)', '', '', ARRAY['Góc chiếu Bất Bất Hợp', 'Sao Mộc', 'Sao Hỏa']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mars', 'Saturn', 'conjunction', 'Sự hợp nhất mạnh mẽ giữa Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục) và Sao Thổ (tính kỷ luật, tinh thần trách nhiệm và các giới hạn). Hai nguồn năng lượng hòa làm một, tạo nên điểm nhấn cá tính vô cùng mãnh liệt.', 'Trong cuộc sống hàng ngày, bạn thể hiện năng lượng hành động, lòng dũng cảm và ham muốn chinh phục và tính kỷ luật, tinh thần trách nhiệm và các giới hạn một cách đồng thời. Bạn hành động bộc phát theo bản năng hòa quyện của cả hai hành tinh.', 'Khả năng tập trung năng lượng vượt trội, sự nhất quán nội tâm cao và sức mạnh bộc lộ cá tính ấn tượng. (Sao Hỏa - Sao Thổ)', 'Khó phân tách giữa các nhu cầu khác nhau. Dễ bị cuốn vào sự chủ quan và thiếu cái nhìn khách quan đa chiều. (Sao Hỏa - Sao Thổ)', '', '', ARRAY['Góc chiếu Trùng Hợp', 'Sao Hỏa', 'Sao Thổ']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
